\set ON_ERROR_STOP on
begin;
create schema tests;
grant usage on schema tests to authenticated;
create function tests.assert(ok boolean, message text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',message; end if; raise notice 'PASS: %',message; end $$;
insert into auth.users values
 ('00000000-0000-0000-0000-000000000001','owner@example.test',now()),
 ('00000000-0000-0000-0000-000000000002','member@example.test',now()),
 ('00000000-0000-0000-0000-000000000003','stranger@example.test',now());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
do $$ declare w uuid; item uuid; recipe uuid; service uuid; supplier uuid; invoice uuid; il uuid; inv uuid; key uuid:=gen_random_uuid(); d jsonb; first jsonb; q numeric; failed boolean; entry uuid;
begin
 w:=(public.execute_command('onboarding','{"name":"Owner","position":"Secretary"}',gen_random_uuid())->>'id')::uuid;
 perform public.execute_command('onboarding','{"name":"Owner","position":"Secretary"}',gen_random_uuid());
 perform tests.assert((select count(*)=1 from public.workspaces),'First profile setup creates one workspace without a bootstrap code');
 perform tests.assert((select count(*)=1 from public.memberships),'Profile setup retries do not duplicate memberships');
 item:=(public.execute_command('item',jsonb_build_object('workspace_id',w,'name','Rice','unit','kg'),gen_random_uuid())->>'id')::uuid;
 recipe:=(public.execute_command('recipe',jsonb_build_object('workspace_id',w,'name','Rice meal','base_yield',100,'basis','servings','ingredients',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',10))),gen_random_uuid())->>'id')::uuid;
 service:=(public.execute_command('service',jsonb_build_object('workspace_id',w,'title','23 thaal Jaman','kind','gathering','service_date','2026-10-23','planned',23,'buffer',10,'people_per_thaal',8,'recipe_ids',jsonb_build_array(recipe)),gen_random_uuid())->>'id')::uuid;
 select required into q from public.ingredient_demand where service_id=service;
 perform tests.assert(q=20.24,'23 thaals at 8 people = 184 people; buffer applied once');
 perform public.execute_command('service',jsonb_build_object('workspace_id',w,'title','Observance','kind','observance','service_date','2026-10-23','planned',23,'buffer',10,'people_per_thaal',8,'recipe_ids',jsonb_build_array(recipe)),gen_random_uuid());
 perform tests.assert((select count(*)=1 from public.ingredient_demand),'Observances create no ingredient demand');
 d:=jsonb_build_object('workspace_id',w,'item_id',item,'kind','opening','quantity',10,'unit_cost',60,'reason','Opening stock');
 first:=public.execute_command('stock',d,key);perform public.execute_command('stock',d,key);
 perform tests.assert((select sum(quantity)=10 from public.stock_movements where item_id=item),'Duplicate opening request posts once');
 failed:=false;begin perform public.execute_command('stock',d||'{"quantity":20}',key);exception when others then failed:=true;end;
 perform tests.assert(failed,'Idempotency key cannot be reused with another payload');
 failed:=false;begin perform public.execute_command('reserve',jsonb_build_object('workspace_id',w,'id',service),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Insufficient stock blocks reservation');
 supplier:=(public.execute_command('supplier',jsonb_build_object('workspace_id',w,'name','Rice supplier'),gen_random_uuid())->>'id')::uuid;
 invoice:=(public.execute_command('invoice',jsonb_build_object('workspace_id',w,'supplier_id',supplier,'number','INV-001','invoice_date','2026-10-20','lines',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',20,'unit_cost',60))),gen_random_uuid())->>'id')::uuid;
 perform tests.assert((select sum(quantity)=10 from public.stock_movements where item_id=item),'Invoice does not receive stock');
 select id into il from public.invoice_lines where invoice_id=invoice;
 d:=jsonb_build_object('workspace_id',w,'item_id',item,'kind','receipt','quantity',12,'invoice_line_id',il,'reason','Partial delivery');key:=gen_random_uuid();
 perform public.execute_command('stock',d,key);perform public.execute_command('stock',d,key);
 perform tests.assert((select sum(quantity)=22 from public.stock_movements where item_id=item),'Partial delivery adds stock once');
 failed:=false;begin perform public.execute_command('stock',d||'{"quantity":9}',gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Over-receipt blocked');
 -- A return carries the original invoice cost and credits that invoice, then reversal restores it.
 d:=jsonb_build_object('workspace_id',w,'item_id',item,'kind','return','quantity',-2,'invoice_line_id',il,'reason','Supplier return');
 entry:=(public.execute_command('stock',d,gen_random_uuid())->>'id')::uuid;
 perform tests.assert((select sum(quantity)=20 from public.stock_movements where item_id=item),'Supplier return reduces stock');
 perform public.execute_command('reverse_stock',jsonb_build_object('workspace_id',w,'id',entry,'reason','Return cancelled'),gen_random_uuid());
 perform tests.assert((select sum(quantity)=22 from public.stock_movements where item_id=item),'Stock reversal restores quantity with history');
 failed:=false;begin perform public.execute_command('reverse_stock',jsonb_build_object('workspace_id',w,'id',entry,'reason','Duplicate reversal'),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'A movement can only be reversed once');
 perform public.execute_command('payment',jsonb_build_object('workspace_id',w,'invoice_id',invoice,'amount',500,'account','cash'),gen_random_uuid());
 select sum(jl.credit-jl.debit) into q from public.journal_lines jl join public.journal_entries je on je.id=jl.entry_id where je.invoice_id=invoice and jl.account_code='payable';
 perform tests.assert(q=700,'Partial payment leaves correct supplier liability');
 perform public.execute_command('reserve',jsonb_build_object('workspace_id',w,'id',service),gen_random_uuid());
 perform tests.assert((select sum(quantity)=20.24 from public.reservations where service_id=service),'Reservation does not consume physical stock');
 perform public.execute_command('status',jsonb_build_object('workspace_id',w,'id',service,'version',1,'status','draft'),gen_random_uuid());
 perform tests.assert((select count(*)=0 from public.reservations where service_id=service),'Draft transition releases reservations');
 failed:=false;begin perform public.execute_command('service',jsonb_build_object('workspace_id',w,'id',service,'version',1,'title','Stale','service_date','2026-10-23','planned',24,'confirmed',0,'buffer',0,'people_per_thaal',8,'recipe_ids',jsonb_build_array(recipe)),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Stale version rejected');
 d:=jsonb_build_object('workspace_id',w,'service_id',service,'version',2,'consumption',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',20)),'prepared',23,'distributed',22,'leftovers',1,'waste',0);key:=gen_random_uuid();
 perform public.execute_command('production',d,key);perform public.execute_command('production',d,key);
 perform tests.assert((select sum(quantity)=2 from public.stock_movements where item_id=item),'Production consumes once');
 perform tests.assert((select count(*)=1 from public.production_runs),'Production retry preserves one output');
 failed:=false;begin perform public.execute_command('production',d,gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Second production completion blocked');
 failed:=false;begin perform public.execute_command('stock',jsonb_build_object('workspace_id',w,'item_id',item,'kind','waste','quantity',-3,'unit_cost',60,'reason','Spoilage'),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Negative stock blocked');
 perform tests.assert(not exists(select 1 from public.journal_lines group by entry_id having sum(debit)<>sum(credit)),'All journals balance');
 perform tests.assert((select sum(debit)=500 from public.journal_lines jl join public.journal_entries je on je.id=jl.entry_id where account_code='payable' and je.kind='payment'),'Invoice and payment are not two expenses');
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
 perform tests.assert(not public.is_member(w),'Registered account has no workspace access before profile setup');
 failed:=false;begin perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','expense','amount',1,'account','cash','description','Before profile'),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Operational records require completed membership');
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
 perform tests.assert(public.workspace_snapshot()->>'needs_onboarding'='true','New password accounts are prompted for profile setup');
 perform public.execute_command('onboarding','{"name":"Member","position":"Treasurer"}',gen_random_uuid());
 perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','expense','amount','123.45','account','cash','description','Kitchen expense'),gen_random_uuid());
 perform tests.assert(public.is_member(w),'Member completes profile without approval and edits accounts');
 perform public.execute_command('profile',jsonb_build_object('workspace_id',w,'name','Member','position','Secretary'),gen_random_uuid());
 failed:=false;begin perform public.execute_command('transfer',jsonb_build_object('workspace_id',w,'user_id','00000000-0000-0000-0000-000000000003'),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Position label does not grant owner administration');
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 perform public.execute_command('revoke',jsonb_build_object('workspace_id',w,'user_id','00000000-0000-0000-0000-000000000002'),gen_random_uuid());
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
 perform tests.assert(not public.is_member(w),'Revocation immediately blocks membership');
 failed:=false;begin perform public.execute_command('onboarding','{"name":"Member","position":"Secretary"}',gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'A revoked account cannot regain access by repeating profile setup');
 failed:=false;begin perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','expense','amount',1,'account','cash','description','Blocked'),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Revoked member cannot post');
end $$;
-- Additional controls for batches, reconciliation, member balances, and immutable production history.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
do $$ declare w uuid; i uuid; early uuid; issue uuid; adjustment uuid; service uuid; recipe uuid; d jsonb; failed boolean; member text:='00000000-0000-0000-0000-000000000001'; begin
 select id into w from public.workspaces limit 1;
 i:=(public.execute_command('item',jsonb_build_object('workspace_id',w,'name','Batch rice','unit','kg'),gen_random_uuid())->>'id')::uuid;
 perform public.execute_command('stock',jsonb_build_object('workspace_id',w,'item_id',i,'kind','opening','quantity',5,'unit_cost',60,'expiry','2026-12-01','reason','Later expiry'),gen_random_uuid());
 early:=(public.execute_command('stock',jsonb_build_object('workspace_id',w,'item_id',i,'kind','opening','quantity',5,'unit_cost',60,'expiry','2026-11-01','reason','Earlier expiry'),gen_random_uuid())->>'id')::uuid;
 issue:=(public.execute_command('stock',jsonb_build_object('workspace_id',w,'item_id',i,'kind','waste','quantity',-3,'unit_cost',60,'reason','Batch use'),gen_random_uuid())->>'id')::uuid;
 perform tests.assert((select sum(quantity)=3 from public.stock_allocations where issue_id=issue and receipt_id=early),'FEFO chooses earliest expiry before creation order');
 adjustment:=(public.execute_command('reconcile',jsonb_build_object('workspace_id',w,'item_id',i,'counted',9,'reason','Physical count'),gen_random_uuid())->>'id')::uuid;
 perform tests.assert((select sum(quantity)=9 from public.stock_movements where item_id=i),'Reconciliation posts the counted difference');
 perform public.execute_command('reverse_stock',jsonb_build_object('workspace_id',w,'id',adjustment,'reason','Count corrected'),gen_random_uuid());
 perform tests.assert((select sum(quantity)=7 from public.stock_movements where item_id=i),'Reconciliation reversal preserves the original count history');
 perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','advance','member_id',member,'amount',1000,'account','cash','description','Purchase advance'),gen_random_uuid());
 perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','settlement','member_id',member,'amount',400,'account','cash','description','Reviewed advance receipts'),gen_random_uuid());
 failed:=false;begin perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','settlement','member_id',member,'amount',700,'account','cash','description','Too much'),gen_random_uuid());exception when others then failed:=true;end;
 perform tests.assert(failed,'Advance settlements cannot exceed the member balance');
 perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','member_expense','member_id',member,'amount',300,'account','cash','description','Member paid kitchen expense'),gen_random_uuid());
 perform public.execute_command('money',jsonb_build_object('workspace_id',w,'kind','reimbursement','member_id',member,'amount',100,'account','cash','description','Partial reimbursement'),gen_random_uuid());
 perform tests.assert((select sum(jl.credit-jl.debit)=200 from public.journal_lines jl join public.journal_entries je on je.id=jl.entry_id where je.member_id=member::uuid and account_code='reimbursements'),'Partial reimbursement leaves the correct member liability');
 recipe:=(public.execute_command('recipe',jsonb_build_object('workspace_id',w,'name','Partial cooking recipe','base_yield',1,'basis','servings','ingredients',jsonb_build_array(jsonb_build_object('item_id',i,'quantity',1))),gen_random_uuid())->>'id')::uuid;
 service:=(public.execute_command('service',jsonb_build_object('workspace_id',w,'title','Partial service','kind','tiffin','service_date','2026-10-24','planned',3,'buffer',0,'people_per_thaal',8,'recipe_ids',jsonb_build_array(recipe)),gen_random_uuid())->>'id')::uuid;
 d:=jsonb_build_object('workspace_id',w,'service_id',service,'version',1,'consumption',jsonb_build_array(jsonb_build_object('item_id',i,'quantity',1)),'prepared',1,'distributed',1,'leftovers',0,'waste',0,'complete',false);
 perform public.execute_command('production',d,gen_random_uuid());
 perform tests.assert((select status='cooking' from public.services where id=service),'Partial production keeps the service open');
 perform tests.assert((select required=2 from public.ingredient_demand where service_id=service),'Partial production reduces remaining ingredient demand');
 perform public.execute_command('production',d||'{"version":2,"complete":true}',gen_random_uuid());
 perform public.execute_command('production',d||'{"version":3,"complete":true,"amendment":true,"notes":"Extra requested portion"}',gen_random_uuid());
 perform tests.assert((select prepared=3 and distributed=3 from public.services where id=service),'Additional production accumulates output with explicit amendment');
 perform public.execute_command('recipe',jsonb_build_object('workspace_id',w,'id',recipe,'version',1,'name','Changed recipe','base_yield',1,'basis','servings','ingredients',jsonb_build_array(jsonb_build_object('item_id',i,'quantity',2))),gen_random_uuid());
 perform tests.assert((select bool_and(recipe_snapshot->0->'recipe'->>'name'='Partial cooking recipe') from public.production_runs where service_id=service),'Recipe edits preserve past production snapshots');
 perform tests.assert(not exists(select 1 from public.journal_lines group by entry_id having sum(debit)<>sum(credit)),'Additional postings remain balanced');
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
end $$;
-- RLS is evaluated under the actual API role, including Storage.
set local role authenticated;
select tests.assert((select count(*)=0 from public.items),'Revoked user cannot read items through RLS');
select tests.assert((select count(*)=0 from public.journal_lines),'Revoked user cannot read financial records');
reset role;
set constraints all immediate;
rollback;
